package org.circus.core;

import java.io.*;
import java.util.*;
import java.util.zip.InflaterInputStream;

/** CurrentDC2 loader actual-byte/globals tests for the translated shared core. */
public final class Dc2CrxMemoryTests {
    private static int assertions;
    private static void check(boolean v,String why){assertions++;if(!v)throw new AssertionError(why);}
    private static byte[] bytes(DataInput in)throws IOException{byte[] b=new byte[in.readInt()];in.readFully(b);return b;}
    private static final class Region{int address;byte[] bytes;}
    private static Region[] regions(DataInput in)throws IOException{Region[] r=new Region[in.readInt()];for(int n=0;n<r.length;n++){r[n]=new Region();r[n].address=in.readInt();r[n].bytes=bytes(in);}return r;}
    private static final class Input implements Pc1CrxDecoder.Input{final byte[] raw;int at;final List<String> reads=new ArrayList<>();Input(byte[] raw){this.raw=raw;}public int descriptor(){return 7;}public int read(byte[] dst,int off,int requested){int got=Math.min(requested,raw.length-at);System.arraycopy(raw,at,dst,off,got);at+=got;reads.add(requested+","+got);return got;}}
    private static final Pc1CrxDecoder.Allocator ALLOCATOR=new Pc1CrxDecoder.Allocator(){
        private Pc1CrxDecoder.Allocation known(int size,int seed){return new Pc1CrxDecoder.Allocation(){final byte[] b=new byte[size];{Arrays.fill(b,(byte)seed);}public byte[] bytes(){return b;}public void close(){}};}
        public Pc1CrxDecoder.Allocation image(int size){return known(size,0xa5);}public Pc1CrxDecoder.Allocation temporary(int size){return known(size,0x69);}
    };
    // BEGIN MACHINE VECTORS
    private static final String[] VECTORS={
        "",
        "",
        "",
        "",
        ""
    };
    // END MACHINE VECTORS
    public static int run()throws Exception{
        assertions=0;check(VECTORS.length>0,"DC2 current loader machine specimens present");Dc2CrxMemory last=null;
        for(String encoded:VECTORS){DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(encoded))));String name=in.readUTF();byte[] raw=bytes(in);Region[] initial=regions(in);int w=in.readInt(),h=in.readInt(),stride=in.readInt(),format=in.readInt();byte[] expected=bytes(in);Region[] after=regions(in);List<String> reads=new ArrayList<>();for(int n=in.readInt();n>0;n--)reads.add(in.readUTF());Dc2CrxMemory memory=new Dc2CrxMemory();last=memory;for(Region r:initial)for(int n=0;n<r.bytes.length;n++)memory.write(r.address+n,r.bytes[n]);Input input=new Input(raw);Pc1CrxDecoder.Decoded value=new Pc1CrxDecoder(memory).decode(input,ALLOCATOR);check(value!=null&&value.width==w&&value.height==h&&value.stride==stride&&value.format==format,"Native DC2 decoder metadata "+name);check(Arrays.equals(value.storage(),expected),"Full native image/padding "+name);for(Region r:after){byte[] actual=new byte[r.bytes.length];for(int n=0;n<actual.length;n++)actual[n]=(byte)memory.read(r.address+n);check(Arrays.equals(actual,r.bytes),"DC2 persistent native buffer/window/header/global bytes "+Integer.toHexString(r.address)+" "+name);}check(input.reads.equals(reads),"Native read counts/EOF "+name);check(!memory.active(),"Decoder releases same DC2 busy fence "+name);
            if(name.equals("actual_rainchip")){check(w==80&&h==136&&stride==240&&format==0,"Actual 224B RainChip native format");Dc2Compositor c=new Dc2Compositor(NativeRgbImage.zeroed(96,100));c.installRgb(20,NativeRgbImage.fromBgr24(w,h,stride,value.storage()));c.setClip(5,6,7,30);c.opacity(5,6,20,7);check(c.rawDirty().left==5&&c.rawDirty().top==6&&c.rawDirty().right==7&&c.rawDirty().bottom==30,"Real atlas reaches persistent native rain strip primitive");}
            if(name.equals("literal_lz_stridepadding")){check(memory.dword(Dc2CrxMemory.BUFFER_POINTER)>=Dc2CrxMemory.BUFFER&&memory.dword(Dc2CrxMemory.BUFFER_POINTER)<Dc2CrxMemory.BUFFER+16384,"Stored encoded pointer uses DC2 native namespace");check((value.storage()[9]&255)==0xa5,"Logical row ignores/retains allocation padding");}
            if(name.equals("stateful_lz_backref"))check((value.storage()[0]&255)==113,"Backref reads canonical DC2 stale window rather than copied PC1 ring");
        }
        int[] pc1={Pc1CrxMemory.HEADER,Pc1CrxMemory.MAGIC,Pc1CrxMemory.BUFFER_COUNT,Pc1CrxMemory.BUFFER,Pc1CrxMemory.DESCRIPTOR,Pc1CrxMemory.WINDOW,Pc1CrxMemory.STRIDE,Pc1CrxMemory.ROWS_LEFT,Pc1CrxMemory.ROW_LEFT,Pc1CrxMemory.PALETTE,Pc1CrxMemory.ROW_BYTES,Pc1CrxMemory.WINDOW_CURSOR,Pc1CrxMemory.BUFFER_POINTER};int[] dc2={Dc2CrxMemory.HEADER,Dc2CrxMemory.MAGIC,Dc2CrxMemory.BUFFER_COUNT,Dc2CrxMemory.BUFFER,Dc2CrxMemory.DESCRIPTOR,Dc2CrxMemory.WINDOW,Dc2CrxMemory.STRIDE,Dc2CrxMemory.ROWS_LEFT,Dc2CrxMemory.ROW_LEFT,Dc2CrxMemory.PALETTE,Dc2CrxMemory.ROW_BYTES,Dc2CrxMemory.WINDOW_CURSOR,Dc2CrxMemory.BUFFER_POINTER};for(int n=0;n<pc1.length;n++)check(last.fieldAddress(pc1[n])==dc2[n],"Explicit per-profile field address "+n);ByteArrayOutputStream out=new ByteArrayOutputStream();last.save(new DataOutputStream(out));byte[] image=Dc2CrxMemory.loadImage(new DataInputStream(new ByteArrayInputStream(out.toByteArray())));int before=last.read(Dc2CrxMemory.WINDOW);last.write(Dc2CrxMemory.WINDOW,0);last.restore(image);check(last.read(Dc2CrxMemory.WINDOW)==before,"D2X1 preserves stateful ring");last.begin();boolean rejected=false;try{last.save(new DataOutputStream(new ByteArrayOutputStream()));}catch(IOException exact){rejected=true;}check(rejected,"Codec fenced inside native IO callback");rejected=false;try{last.begin();}catch(IOException exact){rejected=true;}check(rejected,"Shared native globals cannot reenter");last.end();rejected=false;try{last.read(Dc2CrxMemory.ROW_POINTER);}catch(IOException exact){rejected=true;}check(rejected,"No fabricated native heap row pointer");return assertions;
    }
    public static void main(String[] args)throws Exception{System.out.println("DC2 CRX adapter assertions: "+run());}
}
